def transform(grid):
    h, w = len(grid), len(grid[0])
    # Find a solid row or column that separates two equal-sized panels.
    divider = None
    for r in range(h):
        if len(set(grid[r])) == 1 and h == 2 * (r):
            divider = ("row", r)
            break
    if divider is None:
        for r in range(h):
            if len(set(grid[r])) == 1 and (h - r - 1) == r:
                divider = ("row", r)
                break
    if divider is None:
        for c in range(w):
            if all(grid[r][c] == grid[0][c] for r in range(h)) and w == 2 * c:
                divider = ("col", c)
                break
    if divider is None:
        for c in range(w):
            if all(grid[r][c] == grid[0][c] for r in range(h)) and (w - c - 1) == c:
                divider = ("col", c)
                break
    if divider is None:
        # ARC separators lie between equally sized panels.
        for r in range(h):
            if len(set(grid[r])) == 1 and r == h - r - 1:
                divider = ("row", r)
                break
        for c in range(w):
            if all(grid[r][c] == grid[0][c] for r in range(h)) and c == w - c - 1:
                divider = ("col", c)
                break
    if divider is None:
        raise ValueError("No divider found")
    axis, i = divider
    if axis == "row":
        a, b = grid[:i], grid[i+1:]
    else:
        a = [row[:i] for row in grid]
        b = [row[i+1:] for row in grid]
    shared = set(map(tuple, a))
    # Find the color common to the two panels.
    ca = {v for row in a for v in row}
    cb = {v for row in b for v in row}
    common = ca & cb
    if not common:
        raise ValueError("No shared panel color")
    # The separator color is not part of either panel. ARC task has one shared color.
    color = min(common)
    return [[3 if a[r][c] == color and b[r][c] == color else color
             for c in range(len(a[0]))] for r in range(len(a))]
